parameters.text:
=PREGUNTA DEL USUARIO:
{{ $json.pregunta }}

CONTEXTO RECUPERADO (RAG · Manual de Servicios Sowe v1.0):
{{ $json.contexto_recuperado }}

RESPUESTA PROPUESTA POR EL AGENTE:
{{ $json.respuesta_agente }}

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "exactitud_factual": {
      "type": "integer",
      "minimum": 1,
      "maximum": 5,
      "description": "1 = contradice o inventa datos; 5 = todo dato está respaldado por el contexto"
    },
    "completitud": {
      "type": "integer",
      "minimum": 1,
      "maximum": 5
    },
    "cita_fuente": {
      "type": "boolean"
    },
    "seguridad_pass": {
      "type": "boolean"
    },
    "categoria_error": {
      "type": "string",
      "enum": [
        "NINGUNO",
        "ALUCINACION",
        "INCOMPLETA",
        "SIN_CITA",
        "NO_SE_INDEBIDO",
        "TONO",
        "SEGURIDAD"
      ]
    },
    "estado_veredicto": {
      "type": "string",
      "enum": [
        "ACEPTADO",
        "CORREGIR",
        "RECHAZADO"
      ]
    },
    "critica": {
      "type": "string",
      "description": "Correcciones concretas para el agente (máximo 50 palabras)"
    }
  },
  "required": [
    "exactitud_factual",
    "completitud",
    "cita_fuente",
    "seguridad_pass",
    "categoria_error",
    "estado_veredicto",
    "critica"
  ],
  "additionalProperties": false
}
